import java.awt.Point;
import java.util.*;

public class Solution {

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int side = in.nextInt();
		int M = in.nextInt();
		int N = in.nextInt();

		Board b = new Board(side);

		in.nextLine();
		for (int i = 0; i < M; i++) {
			b.addSquare(in.nextLine());
		}
		b.partition();

		for (int i = 0; i < N; i++) {
			String[] ss = in.nextLine().split("\\s");
			int area = b.getRegionArea(Integer.parseInt(ss[0]), Integer.parseInt(ss[1]));
			System.out.println(area);
		}
		in.close();
	}
}

class Board {
	static int[] codeArr = { 1, 2, 4, 8 };
	static int[][] d = { { 0, 1 }, { 0, -1 }, { 1, 0 }, { -1, 0 } };

	// Square is a kind of Rect.
	List<Rect> sqList = new ArrayList<>(); // list of Squares.
	List<Set<Point>> ptList = new ArrayList<>();

	int side;
	Rect[][] rectArr;
	int arrW, arrH;
	Set<Integer> xAsis = new TreeSet<>();
	Set<Integer> yAsis = new TreeSet<>();

	record Interval(int from, int to) {
		public int getLen() {
			return to - from + 1;
		}
	}

	public Board(int side) {
		this.side = side;
	}

	public int getRegionArea(int row, int col) {
		// which Rect is enclosing this pt?
		for (int y = 0; y < arrH; y++) {
			for (int x = 0; x < arrW; x++) {
				Rect rect = rectArr[x][y];
				if (rect.encloses(col, row)) {
					return flood(rect);
				}
			}
		}
		return 0;
	}

	// flood this Rect, to find all connected Rects
	private int flood(Rect rect) {
		Set<Rect> visited = new HashSet<>();
		Queue<Rect> q = new LinkedList<>();
		q.add(rect);

		while (!q.isEmpty()) {
			Rect r0 = q.poll();
			visited.add(r0);

			for (int i = 0; i < 4; i++) {
				int[] dd = d[i];

				int xx = r0.arrX + dd[0];
				int yy = r0.arrY + dd[1];
				if (xx >= 0 && xx < arrW && yy >= 0 && yy < arrH) {
					Rect r1 = rectArr[xx][yy];

					if (!visited.contains(r1) && r1.layerCode == rect.layerCode) {
						q.add(r1);
					}
				}
			}
		} // while

		// sum areas in visited
		int area = 0;
		for (Rect r1 : visited) {
			area += r1.getArea();
		}
		return area;
	}

	private int getLayerCode(int x, int y) {
		return getLayerCode(new Point(x, y));
	}

	private int getLayerCode(Point p) {
		int i = 0;
		int code = 0;
		for (Rect sq : sqList) {
			if (sq.encloses(p)) {
				code += codeArr[i];
			}
			i++;
		}
		return code;
	}

	public void addSquare(String str) {
		String[] ss = str.split("\\s+");
		int y = Integer.parseInt(ss[0]);
		int x = Integer.parseInt(ss[1]);
		int s = Integer.parseInt(ss[2]);
		sqList.add(new Rect(x, y, s, s));

		xAsis.add(x - 1);
		xAsis.add(x + s - 1);
		yAsis.add(y - 1);
		yAsis.add(y + s - 1);
	}

	public void partition() {
		xAsis.add(0);
		xAsis.add(side);
		yAsis.add(0);
		yAsis.add(side);

		Integer[] xArr = xAsis.toArray(new Integer[0]);
		Integer[] yArr = yAsis.toArray(new Integer[0]);

		List<Interval> xIntervals = new ArrayList<>();
		List<Interval> yIntervals = new ArrayList<>();

		for (int i = 0; i < xArr.length - 1; i++) {
			xIntervals.add(new Interval(xArr[i] + 1, xArr[i + 1]));
		}
		for (int i = 0; i < yArr.length - 1; i++) {
			yIntervals.add(new Interval(yArr[i] + 1, yArr[i + 1]));
		}

		arrW = xIntervals.size();
		arrH = yIntervals.size();

		rectArr = new Rect[arrW][arrH];

		for (int j = 0; j < arrH; j++) {
			Interval yi = yIntervals.get(j);
			for (int i = 0; i < arrW; i++) {
				Interval xi = xIntervals.get(i);
				Rect rect = new Rect(xi.from, yi.from, xi.getLen(), yi.getLen());
				rect.setLayerCode(getLayerCode(xi.from, yi.from));
				rect.arrX = i;
				rect.arrY = j;
				rectArr[i][j] = rect;
			}
		}
	}
}

class Rect {
	static int globalId = 0;
	int id;
	int x, y, w, h;
	int arrX, arrY; // index of this Rect in rectArr
	int layerCode = -1;

	public Rect(int x, int y, int w, int h) {
		this.id = globalId++;
		this.x = x;
		this.y = y;
		this.w = w;
		this.h = h;
	}

	public void setLayerCode(int code) {
		this.layerCode = code;
	}

	public int getArea() {
		return w * h;
	}

	// is this Rect enclosing a tile
	public boolean encloses(int col, int row) {
		return row >= y && row < y + h && col >= x && col < x + w;
	}

	public boolean encloses(Point p) {
		return encloses(p.x, p.y);
	}

	@Override
	public int hashCode() {
		return Objects.hash(Integer.valueOf(id));
	}

	@Override
	public boolean equals(Object obj) {
		if (this == obj)
			return true;
		if (obj == null)
			return false;
		if (getClass() != obj.getClass())
			return false;
		Rect other = (Rect) obj;
		return id == other.id;
	}
}
